<?php use App\Core\PhaseNumber;
use App\Core\Csrf;use App\Core\Format;use App\Core\Auth;
$h=static fn($v)=>Format::h((string)($v??''));$slug=$tenant['slug'];$admin=Auth::isPlatformAdmin();$token=Csrf::token();
?>
<section class="card" style="padding:20px;margin-bottom:16px"><h1>Gestão hierárquica dos processos</h1><p><strong>Processo → Etapa → Fase → Ato → Atividade</strong>. Os documentos permanecem com seus arquivos, versões e aprovação na Gestão Documental. Esta tela inclui a estrutura operacional preservada do banco legado.</p>
<?php if($admin && !empty($modelosOperacionais)):?><details><summary>+ Iniciar processo a partir de um modelo (inclui Fases, Atos e Atividades)</summary><form class="pge-h-form" method="post" action="/<?=$h($slug)?>/hierarquia/salvar"><input type="hidden" name="_token" value="<?=$h($token)?>"><input type="hidden" name="tipo" value="instanciar"><label>Modelo<select name="modelo_id" required><?php foreach($modelosOperacionais as $m):?><option value="<?=$h($m['id'])?>"><?=$h($m['nome'].' — '.$m['versao'])?></option><?php endforeach;?></select></label><label>Nome do novo processo<input name="titulo" required maxlength="255"></label><button class="btn primary">Instanciar estrutura</button></form><p><small>Cria um processo novo; não altera nem vincula documentos históricos a atos diferentes.</small></p></details><?php endif;?>
<?php if($admin):?><details><summary>+ Novo processo</summary><form method="post" action="/<?=$h($slug)?>/hierarquia/salvar"><input type="hidden" name="_token" value="<?=$h($token)?>"><input type="hidden" name="tipo" value="processo"><label>Nome<input name="titulo" required maxlength="255"></label><button class="btn primary">Salvar processo</button></form></details><?php endif;?></section>
<?php foreach($arvoreOperacional as $processo):?>
<section class="card" style="padding:20px;margin-bottom:18px">
<h2>Processo: <?=$h($processo['titulo'])?> <small>· <?=$h($processo['progresso'])?>%</small></h2>
<?php if($admin):?><details><summary>+ Adicionar Etapa</summary><form class="pge-h-form" method="post" action="/<?=$h($slug)?>/hierarquia/salvar"><input type="hidden" name="_token" value="<?=$h($token)?>"><input type="hidden" name="tipo" value="etapa"><input type="hidden" name="processo_id" value="<?=$h($processo['id'])?>"><label>Nome da etapa<input name="titulo" required maxlength="255"></label><button class="btn primary">Criar etapa</button></form></details><?php endif;?>
<?php foreach($processo['etapas'] as $etapa):?>
<div style="margin:16px 0;padding:14px;border:1px solid #b5c6d7;border-radius:9px"><h3>Etapa <?=$h($etapa['numero'])?> — <?=$h($etapa['nome'])?> <small>· <?=$h($etapa['progresso'])?>%</small></h3>
<?php foreach($etapa['fases'] as $fase):?>
<details style="margin:14px 0;border-left:4px solid #6183b4;padding:10px" open><summary><strong>Fase <?=$h(PhaseNumber::from($fase))?> — <?=$h($fase['titulo'])?> · <?=$h($fase['progresso'])?>%</strong></summary>
<p><a href="/<?=$h($slug)?>/workflow/fase/<?=$h($fase['id'])?>">Abrir workflow e documentos da fase</a></p>
<?php foreach($fase['atos'] as $ato):?>
<div style="padding:12px;margin:9px 0 9px 14px;border-left:3px solid #8aaccf;background:var(--surface,#f5f7fc)"><strong>Ato <?=$h($ato['codigo'])?> — <?=$h($ato['titulo'])?></strong> <span>· <?=$h($ato['progresso'])?>%</span>
<?php if($ato['fundamento_normativo']):?><p><small>Fundamento: <?=$h($ato['fundamento_normativo'])?></small></p><?php endif;?>
<?php foreach($ato['atividades'] as $atividade):?>
<div style="margin:9px 0 9px 20px;border-left:2px solid #a5b4c7;padding:8px"><strong>Atividade <?=$h($atividade['codigo'])?> — <?=$h($atividade['titulo'])?></strong> · <?=$h($atividade['status_execucao'])?>
<?php if($atividade['prazo_texto']):?><p><small>Prazo: <?=$h($atividade['prazo_texto'])?></small></p><?php endif;?>
<?php if($admin):?><form method="post" action="/<?=$h($slug)?>/hierarquia/atividades/<?=$h($atividade['id'])?>/status"><input type="hidden" name="_token" value="<?=$h($token)?>"><input type="hidden" name="status" value="<?=$atividade['status_execucao']==='CONCLUIDA'?'PENDENTE':'CONCLUIDA'?>"><button class="btn neutral" type="submit"><?=$atividade['status_execucao']==='CONCLUIDA'?'Reabrir':'Concluir'?></button></form><?php endif;?>
<?php foreach($atividade['documentos'] as $doc):?><p>📎 <a href="/<?=$h($slug)?>/documentos/<?=$h($doc['id'])?>/auditoria"><?=$h($doc['nome'])?></a> · <?=$h($doc['documento_status']??'Não enviado')?></p><?php endforeach;?>
</div><?php endforeach;?>
<?php if($admin && $ato['atividades'] && $ato['documentos']):?><details><summary>Vincular documentos do ato às atividades</summary><form class="pge-h-form" method="post" action="/<?=$h($slug)?>/hierarquia/salvar"><input type="hidden" name="_token" value="<?=$h($token)?>"><input type="hidden" name="tipo" value="documento"><label>Documento<select name="requisito_id" required><?php foreach($ato['documentos'] as $doc):?><option value="<?=$h($doc['id'])?>"><?=$h($doc['nome'])?></option><?php endforeach;?></select></label><label>Atividade<select name="atividade_ato_id" required><?php foreach($ato['atividades'] as $a):?><option value="<?=$h($a['id'])?>"><?=$h($a['titulo'])?></option><?php endforeach;?></select></label><button class="btn primary">Vincular</button></form></details><?php endif;?>
<?php foreach($ato['documentos'] as $doc):?><p>📎 Documento do ato: <a href="/<?=$h($slug)?>/documentos/<?=$h($doc['id'])?>/auditoria"><?=$h($doc['nome'])?></a> · <?=$h($doc['documento_status']??'Não enviado')?></p><?php endforeach;?>
<?php if($admin):?><details><summary>+ Nova Atividade neste Ato</summary><form class="pge-h-form" method="post" action="/<?=$h($slug)?>/hierarquia/salvar"><input type="hidden" name="_token" value="<?=$h($token)?>"><input type="hidden" name="tipo" value="atividade"><input type="hidden" name="ato_id" value="<?=$h($ato['id'])?>"><label>Ordem<input type="number" min="1" name="ordem" value="<?=count($ato['atividades'])+1?>"></label><label>Código<input name="codigo" maxlength="80" placeholder="Ex. 2.1.1"></label><label>Atividade<input name="titulo" maxlength="255" required></label><label>Responsável<input name="responsavel" maxlength="180"></label><label>Prazo<input name="prazo_texto" maxlength="255"></label><label>Descrição<textarea name="descricao"></textarea></label><button class="btn primary">Cadastrar atividade</button></form></details>
<?php endif;?></div><?php endforeach;?>
<?php foreach($fase['documentos'] as $doc):?><p>📎 Documento geral da fase: <a href="/<?=$h($slug)?>/documentos/<?=$h($doc['id'])?>/auditoria"><?=$h($doc['nome'])?></a></p><?php endforeach;?>
</details><?php endforeach;?>
</div><?php endforeach;?></section><?php endforeach;?>
